{{ config(
            materialized='table',
                post_hook={
                    "sql": "Create or replace table MAPLEMONK.IZF_PANDL as select customer_id_final, acquisition_date, first_complete_order_date, Order_Quantity, maple_monk_id_phone, customer_id, SHOP_NAME, coalesce(sc.marketplace,mc.marketplace) marketplace, coalesce(sc.CHANNEL,mc.channel) CHANNEL, SOURCE, cast(ORDER_ID as string) ORDER_ID, cast(sc.reference_code as string)reference_code , PHONE, sc.NAME, Coalesce(sc.gender,cf.gender) AS Gender, EMAIL, SHIPPING_LAST_UPDATE_DATE, coalesce(sc.SKU,rc.SKU) AS SKU, PRODUCT_ID, PRODUCT_NAME, CURRENCY, CITY, State, ORDER_STATUS, coalesce(sc.Order_Date,mc.date) as Order_Date, Order_Time, QUANTITY, GROSS_SALES_BEFORE_TAX, DISCOUNT, TAX, 0 as SHIPPING_PRICE, SELLING_PRICE, OMS_order_status, SHIPPING_STATUS, FINAL_SHIPPING_STATUS, sc.SALEORDERITEMCODE, SALES_ORDER_ITEM_ID, AWB, cast(Payment_Mode as string) as PAYMENT_GATEWAY, Payment_Mode, COURIER, DISPATCH_DATE, DELIVERED_DATE, DELIVERED_STATUS, RETURN_FLAG, returned_sales, cancelled_quantity, Days_in_Shipment, MARKETPLACE_ACQUISITION_DATE, coalesce(sc.SKU_CODE,p.skucode) AS SKU_CODE, PRODUCT_NAME_FINAL, coalesce(sc.PRODUCT_CATEGORY, rc.PRODUCT_CATEGORY) AS Product_Category, PRODUCT_SUB_CATEGORY, commonsku, WAREHOUSE, pincode, source_pincode, coalesce(sc.sku_style,rc.sku_style) AS sku_style, coalesce(sc.sku_size, rc.sku_size) AS sku_size, new_customer_flag, new_customer_flag_month, acquisition_product, acquisition_channel, acquisition_marketplace, Coalesce(sc.article_type,cf.article_type) article_type, 167 AS Return_Fee, 17 AS pick_pack_Charges, gt.GT_Fee AS GT_Fee, p.MRP AS MRP, p.cost * (ifnull(QUANTITY,0)) AS cogs, FF.PPMP AS Fixed_Fee, safe_divide(ifnull(mc.spend,0) , count(*) over(partition by coalesce(sc.Order_Date,mc.date) ,upper(coalesce(sc.CHANNEL,mc.channel,\'\')) ,upper(coalesce(sc.marketplace,mc.marketplace,\'\') ))) as Marketing_Spend, rc.reference_code as return_reference_code, rc.TOTAL_RETURN_AMOUNT, rc.TOTAL_RETURN_TAX AS RETURN_TAX, rc.RETURNED_QUANTITY_BTW_15_45_DAYS AS RETURNED_QUANTITY from maplemonk.IZF_sales_consolidated sc left join (select * from ( select reference_code, saleorderitemcode, Order_Date, marketplace, MARKETING_CHANNEL, SKU, SKU_STYLE, SKU_SIZE, product_category, TOTAL_RETURN_AMOUNT, TOTAL_RETURN_TAX, RETURNED_QUANTITY_BTW_15_45_DAYS, row_number() over (partition by SKU_STYLE order by 1) rw from maplemonk.izf_returns_consolidated ) where rw = 1 ) rc on lower(sc.reference_code) = lower(rc.reference_code) AND lower(sc.saleorderitemcode) = lower(rc.saleorderitemcode) left join (select CAST(selling_price_lower AS FLOAT64) AS selling_price_lower ,CAST(selling_price_upper AS FLOAT64)as selling_price_upper ,CAST(GT_Fee AS FLOAT64) AS GT_Fee ,start_date ,End_date FROM Maplemonk.Google_Sheets_IZF_Myntra_GT_Fee) gt on sc.selling_price <= gt.selling_price_upper AND sc.selling_price >= gt.selling_price_lower left join (select CAST(AISP_Range_lower AS FLOAT64) AS AISP_Range_lower ,CAST(AISP_Range_upper AS FLOAT64) AS AISP_Range_upper ,CAST(PPMP AS FLOAT64) AS PPMP FROM Maplemonk.Google_Sheets_IZF_Fixed_fee ) FF on sc.selling_price <= FF.AISP_Range_upper AND sc.selling_price >= FF.AISP_Range_lower left join (select * from (select sku as skucode ,CAST(mrp AS FLOAT64) AS MRP ,CAST(cost AS FLOAT64) AS cost ,size ,colour ,tax_rate ,Product_Name as name ,category_name as category ,row_number() over (partition by SKU order by 1) rw from maplemonk.easyecom_izf_product_master ) where rw = 1 ) p on lower(sc.sku) = lower(p.skucode) left join ( SELECT UPPER(BRAND) AS Brand, UPPER(MASTER_CATEGORY) AS Master_category, Article_Type, Gender, CAST(Lower_Limit AS FLOAT64) AS Lower_Limit, CAST(Upper_limit AS FLOAT64) AS Upper_limit, Commission_Model, Commission FROM Maplemonk.Google_Sheets_IZF_commission_fee )cf ON LOWER(sc.article_type)= LOWER(cf.article_type) AND sc.selling_price <= cf.upper_limit AND sc.selling_price >= cf.Lower_Limit AND sc.gender=cf.gender full outer join ( select date ,upper(ifnull(channel,\'\')) channel ,case when upper(ifnull(channel,\'\')) like \'%AMAZON%\' then \'AMAZON\' else \'WEBSITE\' end as marketplace ,sum(ifnull(spend,0)) spend from maplemonk.IZF_MARKETING_CONSOLIDATED group by 1,2,3 )mc on sc.order_date = mc.date and upper(ifnull(sc.channel,\'\')) = upper(mc.channel) and upper(mc.marketplace) = upper(sc.marketplace) ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from maplemonk.INFORMATION_SCHEMA.TABLES
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            